def _modules(masked_text: str) -> tuple[_Module, ...]:
    modules: list[_Module] = []
    open_module: tuple[
        str, int, list[str], list[_Sentence]
    ] | None = None
    open_rule_until = 0
    for line_start, line_end, keyword, rest in _line_heads(masked_text):
        if line_start < open_rule_until:
            continue
        open_rule_until = 0
        separated = bool(rest) and rest[0] in " \t"
        if keyword == "module":
            if not separated:
                raise KRuleInventoryError(
                    "verification.k has malformed module boundaries"
                )
            named = _MODULE_NAME_RE.fullmatch(rest)
            if named is None or open_module is not None:
                raise KRuleInventoryError(
                    "verification.k has malformed module boundaries"
                )
            open_module = (named.group("name"), line_end, [], [])
            continue
        if keyword == "endmodule":
            if rest.strip():
                raise KRuleInventoryError(
                    "verification.k has malformed module boundaries"
                )
            if open_module is None:
                raise KRuleInventoryError(
                    "verification.k has malformed module boundaries"
                )
            name, content_start, imports, sentences = open_module
            modules.append(
                _Module(
                    name=name,
                    content_start=content_start,
                    content_end=line_start,
                    imports=tuple(imports),
                    sentences=tuple(sentences),
                )
            )
            open_module = None
            continue
        if open_module is not None and keyword == "rule":
            open_module[3].append(
                _Sentence(keyword=keyword, start=line_start)
            )
            open_rule_until = _rule_bubble_end(masked_text, line_start)
            continue
        if open_module is not None and keyword == "imports" and separated:
            imported = rest.strip().split()
            if len(imported) != 1:
                raise KRuleInventoryError(
                    "verification.k has malformed imports"
                )
            open_module[2].append(imported[0])
        if (
            open_module is not None
            and keyword in _OUTER_SENTENCE_KEYWORDS
            and separated
        ):
            open_module[3].append(
                _Sentence(keyword=keyword, start=line_start)
            )
    if not modules or open_module is not None:
        raise KRuleInventoryError(
            "verification.k has malformed module boundaries"
        )
    return tuple(modules)


def _verification_module(
    modules: tuple[_Module, ...], selected_name: str | None = None
) -> _Module:
    if selected_name is not None:
        selected = [module for module in modules if module.name == selected_name]
        if len(selected) != 1:
            raise KRuleInventoryError(
                "prove.sh selects an unknown verification main module: "
                + selected_name
            )
        return selected[0]
    candidates = [
        module
        for module in modules
        if module.name.endswith("VERIFICATION")
        and not module.name.endswith("-SYNTAX")
    ]
    if len(candidates) != 1:
        raise KRuleInventoryError(
            "verification.k must contain exactly one verification module"
        )
    return candidates[0]


def _last_verification_main_module(workspace: Path) -> str | None:
    script = workspace / "prove.sh"
    if not script.exists() and not script.is_symlink():
        return None
    try:
        mode = script.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise KRuleInventoryError(f"cannot inspect prove.sh: {script}") from error
    if not stat.S_ISREG(mode):
        raise KRuleInventoryError(f"prove.sh must be a regular file: {script}")
    try:
        text = script.read_text()
    except (OSError, UnicodeError) as error:
        raise KRuleInventoryError(f"cannot read prove.sh: {script}") from error
    logical = re.sub(r"\\\r?\n", " ", text)
    selected: str | None = None
    for line in logical.splitlines():
        code = line.split("#", 1)[0]
        if not re.search(r"(?:^|[;&|]\s*)kompile\s+", code):
            continue
        if re.search(r"(?:^|\s)(?:\./)?verification\.k(?:\s|$)", code) is None:
            continue
        match = re.search(
            r"(?:^|\s)--main-module(?:=|\s+)([A-Za-z][A-Za-z0-9_'-]*)",
            code,
        )
        if match is not None:
            selected = match.group(1)
    return selected


def _verification_closure(
    modules: tuple[_Module, ...], verification: _Module
) -> tuple[_Module, ...]:
    by_name = {module.name: module for module in modules}
    reached: set[str] = set()
    pending = [verification.name]
    while pending:
        name = pending.pop()
        if name in reached:
            continue
        reached.add(name)
        module = by_name.get(name)
        if module is not None:
            pending.extend(module.imports)
    return tuple(module for module in modules if module.name in reached)


def _without_comments(text: str) -> str:
    """Remove K comments while preserving strings and their exact contents."""

    output: list[str] = []
    index = 0
    block_depth = 0
    state = "code"
    while index < len(text):
        character = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if state == "line-comment":
            if character in "\r\n":
                output.append(character)
                state = "code"
            index += 1
            continue
        if state == "string":
            output.append(character)
            if character == "\\" and following:
                output.append(following)
                index += 2
                continue
            if character == '"':
                state = "code"
            index += 1
            continue
        if state == "block-comment":
            if character == "/" and following == "*":
                block_depth += 1
                index += 2
                continue
            if character == "*" and following == "/":
                block_depth -= 1
                index += 2
                if block_depth == 0:
                    state = "code"
                continue
            if character in "\r\n":
                output.append(character)
            index += 1
            continue
        if character == "/" and following == "/":
            output.append(" ")
            state = "line-comment"
            index += 2
            continue
        if character == "/" and following == "*":
            output.append(" ")
            state = "block-comment"
            block_depth = 1
            index += 2
            continue
        output.append(character)
        if character == '"':
            state = "string"
        index += 1
    return "".join(output)


def _attribute_tokens(text: str, masked_text: str) -> list[str]:
    tokens: list[str] = []
    start = 0
    depth = 0
    for index, character in enumerate(masked_text):
        if character in "([{":
            depth += 1
        elif character in ")]}":
            depth = max(depth - 1, 0)
        elif character == "," and depth == 0:
            token = _without_comments(text[start:index]).strip()
            if token:
                tokens.append(token)
            start = index + 1
    final = _without_comments(text[start:]).strip()
    if final:
        tokens.append(final)
    return tokens


def _rule_spans(text: str, module: _Module) -> list[_RuleSpan]:
    masked_text = _mask_non_code(text)
    sentences = module.sentences
    rules: list[_RuleSpan] = []
    seen_hashes: set[str] = set()
    for index, sentence in enumerate(sentences):
        if sentence.keyword != "rule":
            continue
        end_offset = (
            sentences[index + 1].start
            if index + 1 < len(sentences)
            else module.content_end
        )
        start_offset = sentence.start
        raw_segment = text[start_offset:end_offset]
        masked_segment = masked_text[start_offset:end_offset]
        logical_length = len(masked_segment.rstrip(" \t\r\n"))
        if logical_length == 0:
            continue
        rule_text = raw_segment[:logical_length].rstrip(" \t\r\n")
        masked_rule = _mask_non_code(rule_text)
        attribute_match = _TRAILING_ATTRIBUTES_RE.search(masked_rule)
        attribute_start = None
        attribute_end = None
        attributes: list[str] = []
        if attribute_match is not None:
            attribute_start = attribute_match.start("attributes")
            attribute_end = attribute_match.end("attributes")
            attributes = _attribute_tokens(
                rule_text[attribute_start:attribute_end],
                masked_rule[attribute_start:attribute_end],
            )
        normalized = " ".join(rule_text.split())
        digest = hashlib.sha256(normalized.encode()).hexdigest()
        if digest in seen_hashes:
            raise KRuleInventoryError(
                f"duplicate normalized simplification rule hash: {digest}"
            )
        seen_hashes.add(digest)
        start_line = text.count("\n", 0, start_offset) + 1
        end_line = start_line + rule_text.count("\n")
        rule = KRule(
            source_rule_id=f"rule-{digest}",
            module=module.name,
            start_line=start_line,
            end_line=end_line,
            normalized_sha256=digest,
            attributes=attributes,
            text=rule_text,
        )
        rules.append(
            _RuleSpan(
                rule=rule,
                start_offset=start_offset,
                end_offset=start_offset + len(rule_text),
                attribute_start=(
                    None
                    if attribute_match is None
                    else start_offset + attribute_match.start()
                ),
                attribute_end=(
                    None
                    if attribute_match is None
                    else start_offset + attribute_match.end()
                ),
            )
        )
    return rules


def _rule_documents(
    text: str, modules: tuple[_Module, ...]
) -> list[dict[str, Any]]:
    spans = [span for module in modules for span in _rule_spans(text, module)]
    spans.sort(key=lambda span: span.start_offset)
    return [dataclasses.asdict(span.rule) for span in spans]


def _attribute_token_spans(
    text: str,
    masked_text: str,
) -> list[tuple[int, int, str]]:
    spans: list[tuple[int, int, str]] = []
    start = 0
    depth = 0
    for index, character in enumerate(masked_text):
        if character in "([{":
            depth += 1
        elif character in ")]}":
            depth = max(depth - 1, 0)
        elif character == "," and depth == 0:
            spans.append(
                (
                    start,
                    index,
                    _without_comments(text[start:index]).strip(),
                )
            )
            start = index + 1
    spans.append(
        (
            start,
            len(text),
            _without_comments(text[start:]).strip(),
        )
    )
    return spans


def _blank_non_newlines(text: str) -> str:
    return "".join(
        character if character in "\r\n" else " "
        for character in text
    )


def desimplify_rule_ids(
    text: str,
    source_rule_ids: list[str],
) -> str:
    """Remove simplification from exactly the selected canonical rule IDs."""

    if len(source_rule_ids) != len(set(source_rule_ids)):
        raise KRuleInventoryError(
            "exact rule transformation contains a duplicate source rule ID"
        )
    selected = set(source_rule_ids)
    modules = _modules(_mask_non_code(text))
    spans = [
        span
        for local_module in modules
        for span in _rule_spans(text, local_module)
    ]
    by_id = {span.rule.source_rule_id: span for span in spans}
    unknown = sorted(selected - set(by_id))
    if unknown:
        raise KRuleInventoryError(
            "exact rule transformation names an unknown source rule ID: "
            + ", ".join(unknown)
        )

    edits: list[tuple[int, int]] = []
    for source_rule_id in source_rule_ids:
        span = by_id[source_rule_id]
        if span.attribute_start is None or span.attribute_end is None:
            raise KRuleInventoryError(
                "selected source rule has no simplification attribute: "
                f"{source_rule_id}"
            )
        attribute_text = text[
            span.attribute_start + 1 : span.attribute_end - 1
        ]
        masked_attributes = _mask_non_code(attribute_text)
        tokens = _attribute_token_spans(
            attribute_text,
            masked_attributes,
        )
        matches = [
            index
            for index, (_start, _end, token) in enumerate(tokens)
            if token == "simplification"
        ]
        if len(matches) != 1:
            raise KRuleInventoryError(
                "selected source rule has ambiguous simplification "
                f"attributes: {source_rule_id}"
            )
        token_index = matches[0]
        if len(tokens) == 1:
            edit_start = span.attribute_start
            edit_end = span.attribute_end
        elif token_index < len(tokens) - 1:
            edit_start = (
                span.attribute_start + 1 + tokens[token_index][0]
            )
            edit_end = (
                span.attribute_start + 1 + tokens[token_index + 1][0]
            )
        else:
            edit_start = (
                span.attribute_start + 1 + tokens[token_index - 1][1]
            )
            edit_end = (
                span.attribute_start + 1 + tokens[token_index][1]
            )
        edits.append((edit_start, edit_end))

    transformed = text
    for start, end in sorted(edits, reverse=True):
        transformed = (
            transformed[:start]
            + _blank_non_newlines(transformed[start:end])
            + transformed[end:]
        )
    return transformed


def inventory_verification(workspace: Path) -> dict[str, Any]:
    workspace = Path(workspace)
    try:
        workspace_mode = workspace.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        ) from error
    if not stat.S_ISDIR(workspace_mode):
        raise KRuleInventoryError(
            f"workspace must be a real directory: {workspace}"
        )
    verification = workspace / "verification.k"
    try:
        verification_mode = verification.stat(
            follow_symlinks=False
        ).st_mode
    except OSError as error:
        raise KRuleInventoryError(
            f"workspace has no regular verification.k: {verification}"
        ) from error
    if not stat.S_ISREG(verification_mode):
        raise KRuleInventoryError(
            f"workspace has no regular verification.k: {verification}"
        )
    try:
        verification_bytes = verification.read_bytes()
        text = verification_bytes.decode()
    except (OSError, UnicodeError) as error:
        raise KRuleInventoryError(
            f"cannot read verification.k: {verification}"
        ) from error
    masked_text = _mask_non_code(text)
    modules = _modules(masked_text)
    module = _verification_module(
        modules, _last_verification_main_module(workspace)
    )
    closure = _verification_closure(modules, module)
    rule_documents = _rule_documents(text, closure)
    return {
        "schema_version": 2,
        "verification_file": "verification.k",
        "verification_sha256": hashlib.sha256(verification_bytes).hexdigest(),
        "verification_module": module.name,
        "verification_modules": [module.name for module in closure],
        "rules": rule_documents,
        "inventory_sha256": canonical_json_sha256(rule_documents),
    }

#!/usr/bin/env python3
"""Validate Stage 3 classifications against the canonical K rule inventory."""

from __future__ import annotations

import json
import stat
from pathlib import Path
from typing import Any

from tools.k_rule_inventory import KRuleInventoryError, inventory_verification


_MANIFEST_KEYS = {"schema_version", "inventory_sha256", "rules"}
_RULE_KEYS = {"source_rule_id", "classification", "rationale"}
_CLASSIFICATIONS = {
    "DEFINITION",
    "OPERATIONAL_RULE",
    "PROVED_DERIVED_LEMMA",
    "DOMAIN_LEMMA",
}


class LemmaDiscoveryContractError(RuntimeError):
    """Raised when a Stage 3 manifest crosses its trust boundary."""


def _regular_json(path: Path) -> dict[str, Any]:
    path = Path(path)
    try:
        mode = path.stat(follow_symlinks=False).st_mode
    except OSError as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        ) from error
    if not stat.S_ISREG(mode):
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest must be a regular file: {path}"
        )
    try:
        document = json.loads(path.read_bytes())
    except (OSError, UnicodeError, ValueError) as error:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is malformed: {path}"
        ) from error
    if not isinstance(document, dict):
        raise LemmaDiscoveryContractError(
            "lemma discovery manifest must be a JSON object"
        )
    return document


def _exact_keys(
    document: dict[str, Any], expected: set[str], label: str
) -> None:
    unexpected = sorted(set(document) - expected)
    if unexpected:
        raise LemmaDiscoveryContractError(
            f"{label} has unexpected key: {unexpected[0]}"
        )
    missing = sorted(expected - set(document))
    if missing:
        raise LemmaDiscoveryContractError(
            f"{label} is missing key: {missing[0]}"
        )


def validate_trust_boundary(
    workspace: Path, manifest: Path
) -> dict[str, Any]:
    try:
        inventory = inventory_verification(Path(workspace))
    except KRuleInventoryError as error:
        raise LemmaDiscoveryContractError(str(error)) from error
    document = _regular_json(Path(manifest))
    _exact_keys(document, _MANIFEST_KEYS, "lemma discovery manifest")
    schema_version = document["schema_version"]
    if (
        not isinstance(schema_version, int)
        or isinstance(schema_version, bool)
        or schema_version != 2
    ):
        raise LemmaDiscoveryContractError(
            "lemma discovery schema_version must be 2"
        )
    if document["inventory_sha256"] != inventory["inventory_sha256"]:
        raise LemmaDiscoveryContractError(
            "lemma discovery inventory_sha256 does not match canonical inventory"
        )
    entries = document["rules"]
    if not isinstance(entries, list):
        raise LemmaDiscoveryContractError(
            "lemma discovery rules must be a JSON list"
        )
    canonical_rules = inventory["rules"]
    canonical_by_id = {
        rule["source_rule_id"]: rule for rule in canonical_rules
    }
    classified_by_id: dict[str, dict[str, str]] = {}
    for index, entry in enumerate(entries):
        label = f"lemma discovery rule {index}"
        if not isinstance(entry, dict):
            raise LemmaDiscoveryContractError(f"{label} must be an object")
        _exact_keys(entry, _RULE_KEYS, label)
        source_rule_id = entry["source_rule_id"]
        if not isinstance(source_rule_id, str) or not source_rule_id:
            raise LemmaDiscoveryContractError(
                f"{label} source_rule_id must be a nonempty string"
            )
        if source_rule_id in classified_by_id:
            raise LemmaDiscoveryContractError(
                f"duplicate lemma discovery source_rule_id: {source_rule_id}"
            )
        if source_rule_id not in canonical_by_id:
            raise LemmaDiscoveryContractError(
                f"unknown lemma discovery source_rule_id: {source_rule_id}"
            )
        classification = entry["classification"]
        if (
            not isinstance(classification, str)
            or classification not in _CLASSIFICATIONS
        ):
            raise LemmaDiscoveryContractError(
                f"{label} classification must be DEFINITION, "
                "OPERATIONAL_RULE, PROVED_DERIVED_LEMMA, or DOMAIN_LEMMA"
            )
        canonical_rule = canonical_by_id[source_rule_id]
        if (
            "simplification" in canonical_rule["attributes"]
            and classification
            in {"OPERATIONAL_RULE", "PROVED_DERIVED_LEMMA"}
        ):
            raise LemmaDiscoveryContractError(
                f"{label} simplification rule must be classified as "
                "DEFINITION or DOMAIN_LEMMA"
            )
        rationale = entry["rationale"]
        if not isinstance(rationale, str) or not rationale.strip():
            raise LemmaDiscoveryContractError(
                f"{label} rationale must be a nonempty string"
            )
        classified_by_id[source_rule_id] = {
            "classification": classification,
            "rationale": rationale,
        }
    missing = [
        rule["source_rule_id"]
        for rule in canonical_rules
        if rule["source_rule_id"] not in classified_by_id
    ]
    if missing:
        raise LemmaDiscoveryContractError(
            f"lemma discovery manifest is missing source_rule_id: {missing[0]}"
        )
    definitions: list[dict[str, Any]] = []
    operational_rules: list[dict[str, Any]] = []
    proved_derived_lemmas: list[dict[str, Any]] = []
    domain_lemmas: list[dict[str, Any]] = []
    for rule in canonical_rules:
        classification = classified_by_id[rule["source_rule_id"]]
        classified_rule = {**rule, **classification}
        role = classification["classification"]
        if role == "DEFINITION":
            definitions.append(classified_rule)
        elif role == "OPERATIONAL_RULE":
            operational_rules.append(classified_rule)
        elif role == "PROVED_DERIVED_LEMMA":
            proved_derived_lemmas.append(classified_rule)
        else:
            domain_lemmas.append(classified_rule)
    return {
        **inventory,
        "definitions": definitions,
        "operational_rules": operational_rules,
        "proved_derived_lemmas": proved_derived_lemmas,
        "domain_lemmas": domain_lemmas,
    }
def check_generation(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    generated = generation / "generated"
    if not frozen_input.is_dir() or frozen_input.is_symlink():
        raise KleanPreflightError("frozen K input must be a real directory")
    if not discovery_manifest.is_file() or discovery_manifest.is_symlink():
        raise KleanPreflightError(
            "validated Stage 3 discovery manifest must be a regular file"
        )
    if not generation.is_dir() or generation.is_symlink():
        raise KleanPreflightError("generation must be a real directory")
    if not generated.is_dir() or generated.is_symlink():
        raise KleanPreflightError("generated project must be a real directory")
    # Traversing every entry rejects symlinks/FIFOs before any build command.
    klean_export._tree_entries(generated)
    snapshot = _preflight_snapshot(
        frozen_input, discovery_manifest, generation
    )
    input_manifest = _regular_json(
        generation / "input-manifest.json", "input manifest"
    )
    generator_manifest = _regular_json(
        generation / "generator-manifest.json", "generator manifest"
    )
    inventory = _regular_json(
        generation / "trust-inventory.json", "trust inventory"
    )
    export_result = _regular_json(
        generation / "export-result.json", "export result"
    )
    lock = _regular_json(Path(toolchain_lock), "toolchain lock")
    export_status = export_result.get("status")
    if export_result.get("schema_version") != 3:
        raise KleanPreflightError("export result schema version is not 3")
    if export_status not in {"OK", "KLEAN_NO_OBLIGATIONS"}:
        raise KleanPreflightError("export result status is invalid")
    input_hash = snapshot.stage1_workspace_sha256
    discovery_hash = snapshot.stage3_discovery_manifest_sha256
    generated_hash = snapshot.generated_tree_sha256
    sidecar_hashes = dict(snapshot.sidecar_sha256)
    if input_manifest.get("schema_version") != 3:
        raise KleanPreflightError("input manifest schema version is not 3")
    if generator_manifest.get("schema_version") != 3:
        raise KleanPreflightError("generator manifest schema version is not 3")
    if input_manifest.get("frozen_input_sha256") != input_hash:
        raise KleanPreflightError("frozen Stage 1 input hash changed")
    if input_manifest.get("stage1_workspace_sha256") != input_hash:
        raise KleanPreflightError("Stage 1 workspace hash changed")
    if (
        input_manifest.get("stage3_discovery_manifest_sha256")
        != discovery_hash
    ):
        raise KleanPreflightError(
            "validated Stage 3 discovery manifest hash changed"
        )
    if generator_manifest.get("generated_tree_sha256") != generated_hash:
        raise KleanPreflightError("generated project hash changed")
    if generator_manifest.get("toolchain") != lock:
        raise KleanPreflightError("generator toolchain differs from pinned lock")
    provenance = generator_manifest.get("provenance")
    if not isinstance(provenance, dict):
        raise KleanPreflightError("generator provenance is malformed")
    if provenance.get("stage1_workspace_sha256") != input_hash:
        raise KleanPreflightError(
            "Stage 1 provenance differs between generation manifests"
        )
    if provenance.get("stage3_discovery_manifest_sha256") != discovery_hash:
        raise KleanPreflightError(
            "Stage 3 provenance differs between generation manifests"
        )
    if provenance.get("inventory_sha256") != input_manifest.get(
        "inventory_sha256"
    ):
        raise KleanPreflightError(
            "Stage 1/Stage 3 inventory provenance differs"
        )
    _source_rules, obligations = _source_and_obligation_gate(
        frozen_input,
        discovery_manifest,
        generated,
        input_manifest,
        generator_manifest,
    )
    expected_export_status = "OK" if obligations else "KLEAN_NO_OBLIGATIONS"
    if export_status != expected_export_status:
        raise KleanPreflightError(
            "export status disagrees with generated obligation count"
        )
    if export_result.get("obligation_count") != len(obligations):
        raise KleanPreflightError(
            "export result obligation_count does not match generated obligations"
        )

    try:
        target = klean_export.target_statement(generated)
    except klean_export.KleanExportError as error:
        raise KleanPreflightError(str(error)) from error
    expected_target = generator_manifest.get("target")
    if target != expected_target:
        raise KleanPreflightError("target theorem statement or location changed")
    if bool(obligations) != bool(target):
        raise KleanPreflightError(
            "target proposition and obligation inventory disagree"
        )
    sources = _lean_sources(generated)
    sorry_locations: list[str] = []
    for source in sources:
        text = source.read_text()
        for forbidden in (r"\badmit\b", r"\bunsafe\b"):
            if re.search(forbidden, text):
                raise KleanPreflightError(
                    f"forbidden Lean token in {source.relative_to(generated)}"
                )
        for match in re.finditer(r"\bsorry\b", text):
            sorry_locations.append(source.relative_to(generated).as_posix())
    if sorry_locations:
        raise KleanPreflightError("generated immutable project contains sorry")
    if inventory.get("designated_sorries") != 0 or inventory.get(
        "other_sorries"
    ) != 0:
        raise KleanPreflightError("trust inventory has unexpected proof-hole counts")

    declared = _trust_declarations(sources)
    _reject_proposition_trust(generated, sources, declared)
    allowlist = inventory.get("allowlist")
    if not isinstance(allowlist, list):
        raise KleanPreflightError("trust inventory allowlist is malformed")
    expected: dict[str, tuple[str, str]] = {}
    for entry in allowlist:
        if not isinstance(entry, dict):
            raise KleanPreflightError("trust allowlist entry is malformed")
        name = entry.get("name")
        kind = entry.get("kind")
        lean_type = entry.get("type")
        reason = entry.get("reason")
        if not all(
            isinstance(value, str) and value
            for value in (name, kind, lean_type, reason)
        ):
            raise KleanPreflightError("trust allowlist entry is incomplete")
        if name in expected:
            raise KleanPreflightError(
                f"duplicate trust allowlist entry: {name}"
            )
        expected[name] = (kind, lean_type)
    if declared != expected:
        raise KleanPreflightError(
            "generated axiom/opaque declarations differ from trust allowlist"
        )
    _check_imports(generated, sources)
    export_bindings = {
        "frozen_input_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "trust_inventory_sha256": sidecar_hashes[
            "trust-inventory.json"
        ],
    }
    for field, expected_hash in export_bindings.items():
        if export_result.get(field) != expected_hash:
            label = (
                "trust inventory hash"
                if field == "trust_inventory_sha256"
                else field
            )
            raise KleanPreflightError(
                f"export result {label} does not match immutable inputs"
            )

    with tempfile.TemporaryDirectory(prefix="klean-preflight-") as temporary:
        clean = Path(temporary) / "project"
        shutil.copytree(generated, clean)
        diagnostics: list[dict[str, Any]] = []
        for command in (["lake", "clean"], ["lake", "build"]):
            code, output = run_command(command, cwd=clean, timeout=600)
            diagnostics.append(
                {
                    "command": command,
                    "exit_code": code,
                    "output_sha256": hashlib.sha256(output.encode()).hexdigest(),
                    "output_tail": output[-4000:],
                }
            )
            if code != 0:
                raise KleanPreflightError(
                    f"{' '.join(command)} failed ({code}): {output[-600:]}"
                )
    _require_unchanged_snapshot(
        snapshot, frozen_input, discovery_manifest, generation
    )
    return {
        "schema_version": 3,
        "status": "PASS" if obligations else "KLEAN_NO_OBLIGATIONS",
        "frozen_input_sha256": input_hash,
        "stage1_workspace_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "target": target,
        "obligation_count": len(obligations),
        "trust_declaration_count": len(declared),
        "designated_sorry_count": 0,
        "diagnostics": diagnostics,
    }


def run_preflight(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    output = generation / "preflight.json"
    if output.exists() or output.is_symlink():
        raise KleanPreflightError(f"preflight result already exists: {output}")

    def error_document(error: KleanPreflightError) -> dict[str, Any]:
        try:
            stage1_hash = klean_export.tree_digest(frozen_input)
        except (OSError, klean_export.KleanExportError):
            stage1_hash = None
        try:
            stage3_hash = hashlib.sha256(
                discovery_manifest.read_bytes()
            ).hexdigest()
        except OSError:
            stage3_hash = None
        return {
            "schema_version": 3,
            "status": "KLEAN_PREFLIGHT_ERROR",
            "error": str(error),
            "stage1_workspace_sha256": stage1_hash,
            "stage3_discovery_manifest_sha256": stage3_hash,
        }

    publication_snapshot: PreflightSnapshot | None = None
    try:
        publication_snapshot = _preflight_snapshot(
            frozen_input, discovery_manifest, generation
        )
        document = check_generation(
            frozen_input,
            discovery_manifest,
            generation,
            toolchain_lock=toolchain_lock,
            run_command=run_command,
        )
        _require_unchanged_snapshot(
            publication_snapshot,
            frozen_input,
            discovery_manifest,
            generation,
        )
    except KleanPreflightError as error:
        document = error_document(error)
    temporary = output.with_name(f".{output.name}.tmp")
    temporary.write_text(json.dumps(document, indent=2, sort_keys=True) + "\n")
    if (
        document.get("status") in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        and publication_snapshot is not None
    ):
        try:
            _require_unchanged_snapshot(
                publication_snapshot,
                frozen_input,
                discovery_manifest,
                generation,
            )
        except KleanPreflightError as error:
            document = error_document(error)
            temporary.write_text(
                json.dumps(document, indent=2, sort_keys=True) + "\n"
            )
    os.replace(temporary, output)
    return document


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--discovery-manifest", required=True, type=Path)
    parser.add_argument("--generation", required=True, type=Path)
    parser.add_argument(
        "--toolchain-lock",
        type=Path,
        default=REPO / "data/klean-toolchain.lock.json",
    )
    arguments = parser.parse_args(argv)
    try:
        result = run_preflight(
            arguments.input,
            arguments.discovery_manifest,
            arguments.generation,
            toolchain_lock=arguments.toolchain_lock,
        )
    except KleanPreflightError as error:
        print(f"Klean preflight failed: {error}", file=sys.stderr)
        return 2
    print(json.dumps(result, sort_keys=True))
    return (
        0
        if result["status"] in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        else 1
    )


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Resolve immutable Stage 6 inputs and allocate independent Klean audits."""

from __future__ import annotations

import argparse
import json
import os
import re
import stat
import sys
from pathlib import Path
from typing import Any

REPO = Path(__file__).resolve().parent.parent
if str(REPO) not in sys.path:
    sys.path.insert(0, str(REPO))

from tools import (
    audit_contract,
    klean_export,
    pipeline_contract,
    stage4_runner,
    stage6_resolution_contract,
)


class KleanAuditContractError(RuntimeError):
    pass


_STAGE6_RESOLUTION_KEYS = stage6_resolution_contract.RESOLUTION_KEYS


def _canonical_json_sha256(document: Any) -> str:
    return stage6_resolution_contract.canonical_json_sha256(document)


def _validate_sha256(value: object, label: str) -> str:
    try:
        return stage6_resolution_contract.validate_sha256(
            value, label
        )
    except (
        stage6_resolution_contract.Stage6ResolutionContractError
    ) as error:
        raise KleanAuditContractError(str(error)) from error


def _stage6_audit_input(
    resolution: dict[str, Any],
) -> dict[str, Any]:
    return stage6_resolution_contract.build_audit_input(resolution)


def verify_stage6_audit_input(
    document: dict[str, Any],
) -> tuple[dict[str, Any], str]:
    try:
        return stage6_resolution_contract.verify_audit_input(document)
    except (
        stage6_resolution_contract.Stage6ResolutionContractError
    ) as error:
        raise KleanAuditContractError(str(error)) from error


def _translate(error: Exception) -> KleanAuditContractError:
    return KleanAuditContractError(str(error))


def _read_json(path: Path, label: str) -> dict[str, Any]:
    try:
        return pipeline_contract._read_regular_json(path, label)
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _selected(
    task: Path, stage_name: str, container_name: str
) -> tuple[Path, dict[str, Any]]:
    try:
        stage = pipeline_contract.require_real_directory(
            task / stage_name, stage_name
        )
        selected = pipeline_contract._read_regular_json(
            stage / "selected.json", f"{stage_name} selection"
        )
        relative = selected.get("relative_path")
        parts = Path(relative).parts if isinstance(relative, str) else ()
        if len(parts) != 2 or parts[0] != container_name:
            raise KleanAuditContractError(
                f"{stage_name} selected path is malformed"
            )
        candidate = pipeline_contract._require_direct_directory(
            stage / container_name,
            parts[1],
            f"selected {stage_name} output",
        )
        if (
            pipeline_contract.sha256_tree(candidate)
            != selected.get("artifact_sha256")
        ):
            noun = (
                "generation"
                if stage_name == "04-klean-generation"
                else "audit"
            )
            raise KleanAuditContractError(
                f"selected {stage_name} {noun} changed after selection"
            )
        return candidate, selected
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _require_stage5(task: Path) -> tuple[Path, Path, dict[str, Any]]:
    try:
        stage = pipeline_contract.require_real_directory(
            task / "05-lean-proof", "Stage 5"
        )
        result = pipeline_contract._read_regular_json(
            stage / "result.json", "Stage 5 result"
        )
        if result.get("status") != "SUCCEEDED":
            raise KleanAuditContractError(
                "Stage 5 must be SUCCEEDED before proof-bearing audit"
            )
        workspace = pipeline_contract.require_real_directory(
            stage / "workspace", "Stage 5 Lean workspace"
        )
        invocation_name = pipeline_contract.validate_safe_component(
            result.get("invocation"), "Stage 5 invocation"
        )
        invocation = pipeline_contract._require_direct_directory(
            stage / "invocations",
            invocation_name,
            "successful Stage 5 invocation",
        )
        invocation_manifest = pipeline_contract._read_regular_json(
            invocation / "invocation.json", "Stage 5 invocation manifest"
        )
        if (
            invocation_manifest.get("status") != "SUCCEEDED"
            or invocation_manifest.get("name") != invocation_name
            or invocation_manifest.get("stage") != "05-lean-proof"
            or invocation_manifest.get("session_id")
            != result.get("session_id")
        ):
            raise KleanAuditContractError(
                "selected Stage 5 invocation is not successful"
            )
        for name in ("metrics.json", "codex-output.log", "codex-last.txt"):
            pipeline_contract.require_regular_file(
                invocation / name, f"Stage 5 {name}"
            )
        pipeline_contract._walk_regular_files(
            invocation / "codex-trace", "Stage 5 Codex trace"
        )
        for name in ("Proof.lean", "lakefile.lean", "lean-toolchain"):
            pipeline_contract.require_regular_file(
                workspace / name, f"Stage 5 {name}"
            )
        current_outputs = pipeline_contract._invocation_output_hashes(
            invocation, workspace
        )
        result_outputs = result.get("outputs")
        invocation_outputs = invocation_manifest.get("outputs")
        if (
            current_outputs.get("workspace_sha256")
            != (
                result_outputs.get("workspace_sha256")
                if isinstance(result_outputs, dict)
                else None
            )
            or current_outputs.get("workspace_sha256")
            != (
                invocation_outputs.get("workspace_sha256")
                if isinstance(invocation_outputs, dict)
                else None
            )
        ):
            raise KleanAuditContractError(
                "Lean workspace changed after Stage 5 succeeded"
            )
        if (
            current_outputs.get("evidence")
            != (
                result_outputs.get("evidence")
                if isinstance(result_outputs, dict)
                else None
            )
            or current_outputs.get("evidence")
            != (
                invocation_outputs.get("evidence")
                if isinstance(invocation_outputs, dict)
                else None
            )
        ):
            raise KleanAuditContractError(
                "Stage 5 invocation evidence changed after success"
            )
        return workspace, invocation, result
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _stage1_source_hashes(workspace: Path) -> dict[str, str]:
    try:
        return {
            path.relative_to(workspace).as_posix(): (
                pipeline_contract.sha256_file(path)
            )
            for path in pipeline_contract._walk_regular_files(
                workspace, "Stage 1 source workspace"
            )
        }
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _generation_producer_sources(
    repo: Path, generator_manifest: dict[str, Any]
) -> tuple[Path, str]:
    provenance = generator_manifest.get("provenance")
    image_id = (
        provenance.get("generator_image_id")
        if isinstance(provenance, dict)
        else None
    )
    if not isinstance(image_id, str) or not image_id.startswith("sha256:"):
        raise KleanAuditContractError(
            "generator image ID is missing from Stage 4 provenance"
        )
    image_key = image_id.removeprefix("sha256:")
    try:
        image_key = pipeline_contract.validate_safe_component(
            image_key, "generator image ID"
        )
        bundle = pipeline_contract._require_direct_directory(
            repo / "data/stage4-producer-sources",
            image_key,
            "Stage 4 producer source bundle",
        )
        source_manifest = pipeline_contract._read_regular_json(
            bundle / "source-manifest.json",
            "Stage 4 producer source manifest",
        )
        expected_files = {
            "klean_export.py": generator_manifest.get("exporter_sha256"),
            "klean.py": generator_manifest.get("klean_py_sha256"),
        }
        if (
            set(source_manifest) != {
                "schema_version",
                "generator_image_id",
                "files",
            }
            or source_manifest.get("schema_version") != 1
            or source_manifest.get("generator_image_id") != image_id
            or source_manifest.get("files") != expected_files
        ):
            raise KleanAuditContractError(
                "Stage 4 producer source manifest differs from generator "
                "provenance"
            )
        observed_names = {
            path.relative_to(bundle).as_posix()
            for path in pipeline_contract._walk_regular_files(
                bundle, "Stage 4 producer source bundle"
            )
        }
        if observed_names != {
            "source-manifest.json",
            "klean_export.py",
            "klean.py",
        }:
            raise KleanAuditContractError(
                "Stage 4 producer source bundle has unexpected files"
            )
        for name, expected in expected_files.items():
            digest = _validate_sha256(
                expected, f"Stage 4 producer source {name} SHA-256"
            )
            source = pipeline_contract.require_regular_file(
                bundle / name, f"Stage 4 producer source {name}"
            )
            if pipeline_contract.sha256_file(source) != digest:
                raise KleanAuditContractError(
                    f"Stage 4 producer source {name} SHA-256 differs "
                    "from generator provenance"
                )
        return bundle, pipeline_contract.sha256_tree(bundle)
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def resolve_stage6_audit(
    repo: Path, run_id: str, problem: str
) -> dict[str, Any]:
    """Resolve and re-hash every frozen input to the Stage 6 audit."""

    try:
        task, _state, run = pipeline_contract._resolve_task_state(
            repo, run_id, problem
        )
        pipeline_contract.require_task_unblocked(task, "Stage 6")
        k_stage = pipeline_contract.require_real_directory(
            task / "01-k-proof", "Stage 1"
        )
        k_workspace = pipeline_contract.require_real_directory(
            k_stage / "workspace", "Stage 1 K workspace"
        )
        k_result = pipeline_contract._read_regular_json(
            k_stage / "result.json", "Stage 1 result"
        )
        if k_result.get("status") != "SUCCEEDED":
            raise KleanAuditContractError("Stage 1 is not successful")
        k_hash = pipeline_contract.sha256_tree(k_workspace)
        if (
            not isinstance(k_result.get("outputs"), dict)
            or k_result["outputs"].get("workspace_sha256") != k_hash
        ):
            raise KleanAuditContractError(
                "Stage 1 K workspace changed after success"
            )
        stage1_export_hash = klean_export.tree_digest(k_workspace)
        stage1_source_hashes = _stage1_source_hashes(k_workspace)

        k_audit, k_audit_selection = _selected(
            task, "02-k-audit", "executions"
        )
        k_verdict = pipeline_contract._read_regular_json(
            k_audit / "verdict.json", "Stage 2 verdict"
        )
        if (
            k_verdict.get("audit_status") != "COMPLETE"
            or k_verdict.get("legitimacy") != "LEGIT"
            or k_verdict.get("verdict") not in {"PASS", "CONCERNS"}
        ):
            raise KleanAuditContractError(
                "Stage 2 must have a selected LEGIT verdict"
            )

        try:
            discovery = stage4_runner._protected_stage3_discovery(task)
        except stage4_runner.Stage4RunnerError as error:
            raise KleanAuditContractError(str(error)) from error

        generation, generation_selection = _selected(
            task, "04-klean-generation", "generations"
        )
        generation_status = generation_selection.get("status")
        if generation_status not in {
            "PASS",
            "KLEAN_NO_OBLIGATIONS",
        }:
            raise KleanAuditContractError(
                "Stage 4 must have a selected passing Klean generation"
            )
        preflight = pipeline_contract._read_regular_json(
            generation / "preflight.json", "Stage 4 preflight"
        )
        if preflight.get("status") != generation_status:
            raise KleanAuditContractError(
                "Stage 4 selection status differs from its preflight"
            )
        generator_manifest = pipeline_contract._read_regular_json(
            generation / "generator-manifest.json", "generator manifest"
        )
        generation_producer_sources, producer_sources_hash = (
            _generation_producer_sources(repo, generator_manifest)
        )
        generated = pipeline_contract.require_real_directory(
            generation / "generated", "generated Klean project"
        )
        generated_hash = klean_export.tree_digest(generated)
        if generator_manifest.get("generated_tree_sha256") != generated_hash:
            raise KleanAuditContractError(
                "selected Stage 4 generation changed after preflight"
            )
        provenance = generator_manifest.get("provenance")
        if (
            not isinstance(provenance, dict)
            or provenance.get("stage1_workspace_sha256")
            != stage1_export_hash
            or provenance.get("stage3_discovery_manifest_sha256")
            != discovery.sha256
        ):
            raise KleanAuditContractError(
                "selected Stage 4 generation provenance is invalid"
            )
        target = generator_manifest.get("target")
        if generation_status == "PASS" and not isinstance(target, dict):
            raise KleanAuditContractError(
                "Stage 4 target manifest is malformed"
            )
        if (
            generation_status == "KLEAN_NO_OBLIGATIONS"
            and target is not None
        ):
            raise KleanAuditContractError(
                "no-obligation Stage 4 generation has an unexpected target"
            )

        lean_workspace: Path | None = None
        lean_invocation: Path | None = None
        lean_result: dict[str, Any] | None = None
        if generation_status == "PASS":
            mode = "CLASSIFICATION_AND_PROOF"
            lean_workspace, lean_invocation, lean_result = (
                _require_stage5(task)
            )
        else:
            mode = "CLASSIFICATION_ONLY"
            stage5_result = task / "05-lean-proof/result.json"
            if stage5_result.exists() or stage5_result.is_symlink():
                raise KleanAuditContractError(
                    "KLEAN_NO_OBLIGATIONS must not have a Stage 5 result"
                )
        condition = run.get("condition")
        if not isinstance(condition, dict):
            raise KleanAuditContractError("run condition is malformed")
        resolved = {
            "schema_version": stage6_resolution_contract.SCHEMA_VERSION,
            "run_id": run_id,
            "problem_id": problem,
            "condition": condition.get("name"),
            "mode": mode,
            "semantics_mode": (
                "SUPPLIED_SEMANTICS"
                if condition.get("semantics") is True
                else "GENERATED_SEMANTICS"
            ),
            "k_workspace": str(k_workspace),
            "k_audit": str(k_audit),
            "discovery_manifest": str(discovery.path),
            "klean_generation": str(generation),
            "generation_producer_sources": str(
                generation_producer_sources
            ),
            "lean_workspace": (
                str(lean_workspace)
                if lean_workspace is not None
                else None
            ),
            "lean_invocation": (
                str(lean_invocation)
                if lean_invocation is not None
                else None
            ),
            "target": target,
            "stage1_source_hashes": stage1_source_hashes,
            "trust_inventory": str(
                pipeline_contract.require_regular_file(
                    generation / "trust-inventory.json",
                    "Stage 4 trust inventory",
                )
            ),
            "hashes": {
                "k_workspace_sha256": k_hash,
                "stage1_export_sha256": stage1_export_hash,
                "discovery_manifest_sha256": discovery.sha256,
                "k_audit_sha256": pipeline_contract.sha256_tree(k_audit),
                "klean_generation_sha256": pipeline_contract.sha256_tree(
                    generation
                ),
                "generation_producer_sources_sha256": (
                    producer_sources_hash
                ),
                "generated_tree_sha256": generated_hash,
                "lean_workspace_sha256": (
                    pipeline_contract.sha256_tree(lean_workspace)
                    if lean_workspace is not None
                    else None
                ),
                "lean_invocation_sha256": (
                    pipeline_contract.sha256_tree(lean_invocation)
                    if lean_invocation is not None
                    else None
                ),
            },
            "selections": {
                "k_audit": k_audit_selection,
                "klean_generation": generation_selection,
            },
            "stage4_preflight": preflight,
            "stage5_result": lean_result,
        }
        return _stage6_audit_input(resolved)
    except klean_export.KleanExportError as error:
        raise KleanAuditContractError(str(error)) from error
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _execution_directories(executions: Path) -> list[Path]:
    try:
        executions = pipeline_contract.require_real_directory(
            executions, "Stage 6 executions"
        )
        children: list[Path] = []
        for entry in os.scandir(executions):
            mode = entry.stat(follow_symlinks=False).st_mode
            path = Path(entry.path)
            if not stat.S_ISDIR(mode) or not re.fullmatch(
                r"[0-9]{3}", path.name
            ):
                raise KleanAuditContractError(
                    f"invalid Stage 6 execution entry: {path}"
                )
            children.append(path)
        return sorted(children)
    except OSError as error:
        raise KleanAuditContractError(
            f"cannot scan Stage 6 executions: {error}"
        ) from error
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error

